package com.carbonedge.backend.repository;
import com.carbonedge.backend.model.QuizAttemptAnswer; import java.util.List; import java.util.Optional; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param;
public interface QuizAttemptAnswerRepository extends JpaRepository<QuizAttemptAnswer, Long> { List<QuizAttemptAnswer> findAllByAttemptId(Long attemptId); Optional<QuizAttemptAnswer> findByAttemptIdAndQuestionId(Long attemptId, Long questionId); void deleteByAttemptId(Long attemptId); @Modifying @Query("delete from QuizAttemptAnswer answer where answer.attempt.quiz.id = :quizId") void deleteByAttemptQuizId(@Param("quizId") Long quizId); }
